    const ConsumableEntry *FindConsumable(std::string_view item) {
        const auto found = std::lower_bound(g_Consumables.begin(), g_Consumables.end(), item, [](const auto &entry, auto id) { return entry.item < id; });
        return found != g_Consumables.end() && found->item == item ? &*found : nullptr;
    }
